using GastricCancerDetection.Application.Interfaces;
using GastricCancerDetection.Infrastructure.Persistence;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Api.Controllers; 
[ApiController][Route("api/analysis")] 
public class AnalysisController : ControllerBase { private readonly IAnalysisService _service; private readonly GastricCancerDbContext _db; public AnalysisController(IAnalysisService service, GastricCancerDbContext db) { _service = service; _db = db; } [HttpGet("runs")] public async Task<IActionResult> Runs(CancellationToken ct) { var runs = await _db.AnalysisRuns.AsNoTracking().OrderByDescending(x => x.RunId).Take(100).ToListAsync(ct); return Ok(runs); } [HttpGet("runs/{id:int}")] public async Task<IActionResult> Run(int id, CancellationToken ct) { var run = await _db.AnalysisRuns.AsNoTracking().FirstOrDefaultAsync(x => x.RunId == id, ct); if (run is null) return NotFound(); return Ok(run); } [HttpPost("run")] public async Task<IActionResult> Run([FromBody] RunRequest request, CancellationToken ct) { if (request.PanelId <= 0) return BadRequest(new { message = "PanelId must be greater than zero." }); if (request.ModelVersionId <= 0) return BadRequest(new { message = "ModelVersionId must be greater than zero." }); if (request.GenomeFileId <= 0) return BadRequest(new { message = "GenomeFileId must be greater than zero." }); try { var genomeFile = await _db.GenomeFiles.AsNoTracking().FirstOrDefaultAsync(x => x.FileId == request.GenomeFileId, ct); if (genomeFile is null) { return NotFound(new { message = "Genome file not found.", genomeFileId = request.GenomeFileId }); } if (string.IsNullOrWhiteSpace(genomeFile.FilePath)) { return BadRequest(new { message = "Genome file path is empty.", genomeFileId = request.GenomeFileId }); } var fullPath = Path.GetFullPath(genomeFile.FilePath); if (!System.IO.File.Exists(fullPath)) { return NotFound(new { message = "Genome file does not exist on disk.", genomeFileId = request.GenomeFileId, path = fullPath }); } var result = await _service.StartAsync(request.PanelId, request.ModelVersionId, ct); return Ok(new { message = "Analysis started successfully.", genomeFileId = request.GenomeFileId, fileName = genomeFile.FileName, filePath = fullPath, result }); } catch (OperationCanceledException) { return StatusCode(StatusCodes.Status499ClientClosedRequest, new { message = "Analysis request was cancelled." }); } catch (Exception ex) { return BadRequest(new { message = ex.Message, innerException = ex.InnerException?.Message }); } } [HttpGet("ranking/{runId:int}")] public async Task<IActionResult> Ranking(int runId, CancellationToken ct) { var candidates = await _db.Candidates.AsNoTracking().Where(x => x.AnalysisRunId == runId).OrderByDescending(x => x.OverallPriority).ToListAsync(ct); return Ok(candidates); } [HttpGet("gene-results/{runId:int}")] public async Task<IActionResult> GeneResults(int runId, CancellationToken ct) { var results = await _db.GeneComparisonResults.AsNoTracking().Where(x => x.RunId == runId).ToListAsync(ct); return Ok(results); } } public record RunRequest(int PanelId, int ModelVersionId, int GenomeFileId);